begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
update public.community_operations set enabled=true,enrollment=true,discovery=true,publish=true,engagement=true,cohort_required=false;
create function pg_temp.media_fixture_receipt() returns trigger language plpgsql as $$begin new.terms_version:='2026-09-30';new.terms_accepted_at:=now();new.adult_declared_at:=now();return new;end $$;
create trigger community_media_fixture_receipt before insert on public.community_profiles for each row execute function pg_temp.media_fixture_receipt();
insert into auth.users(id,email) select ('c1600000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,'comm160-'||i||'@mizyun.test' from generate_series(1,4)i;
update public.profiles set birth_year=extract(year from now())::integer-30 where id::text like 'c1600000%';
insert into public.community_profiles(user_id,handle,display_name,status) select id,'comm160_'||right(id::text,12),'Synthetic member','active' from auth.users where id::text like 'c1600000%';
insert into public.community_relationships(follower_user_id,target_user_id,status) values('c1600000-0000-4000-8000-000000000002','c1600000-0000-4000-8000-000000000001','approved');
insert into public.community_moderation_staff(user_id,active) values('c1600000-0000-4000-8000-000000000004',true);
create temp table media_state(key text primary key,value jsonb);grant all on media_state to authenticated;
set local role authenticated;set local request.jwt.claim.role='authenticated';set local request.jwt.claim.sub='c1600000-0000-4000-8000-000000000001';
select throws_ok($$select public.community_media_begin('{"operationId":"e1600000-0000-4000-8000-000000000001","digest":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa","altText":"A workout room","rightsConfirmed":true}')$$,'P0001','community_unavailable','Default disabled image feature refuses upload ticket');
reset role;update public.community_feature_controls set enabled=true where feature='media';
set local role authenticated;
select throws_ok($$select public.community_media_begin('{"operationId":"e1600000-0000-4000-8000-000000000001","digest":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa","altText":"A workout room","rightsConfirmed":false}')$$,'P0001','community_invalid_input','Explicit rights confirmation required');
insert into media_state values('ticket',public.community_media_begin('{"operationId":"e1600000-0000-4000-8000-000000000001","digest":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa","altText":"A workout room","rightsConfirmed":true}'));
select is((public.community_media_begin('{"operationId":"e1600000-0000-4000-8000-000000000001","digest":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa","altText":"A workout room","rightsConfirmed":true}')->>'id'),(select value->>'id' from media_state where key='ticket'),'Lost begin response safely reuses immutable ticket');
select throws_ok($$select public.community_media_begin('{"operationId":"e1600000-0000-4000-8000-000000000001","digest":"bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb","altText":"A workout room","rightsConfirmed":true}')$$,'P0001','community_conflict','Operation ID cannot replace immutable image bytes');
select lives_ok($$select public.community_media_begin('{"operationId":"e1600000-0000-4000-8000-000000000001","digest":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa","altText":"A workout room","rightsConfirmed":true}')$$,'Third interrupted decode attempt remains recoverable');
select throws_ok($$select public.community_media_begin('{"operationId":"e1600000-0000-4000-8000-000000000001","digest":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa","altText":"A workout room","rightsConfirmed":true}')$$,'P0001','community_rate_limited','Repeated decoder attempts cannot bypass CPU cap via same upload ID');
select throws_ok($$select public.community_media_commit((select (value->>'id')::uuid from media_state where key='ticket'),'c1600000-0000-4000-8000-000000000001',1,'aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa',200,100)$$,'42501',null,'Owner cannot certify unsanitized client bytes');
select throws_ok($$select * from public.community_media_assets$$,'42501',null,'Raw asset table is not exposed');
reset role;set local request.jwt.claim.role='service_role';
select lives_ok($$select public.community_media_commit((select (value->>'id')::uuid from media_state where key='ticket'),'c1600000-0000-4000-8000-000000000001',1,'aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa',200,100)$$,'Service-only decoder commit moves to quarantine review');
-- SQL proves metadata/RLS, not real Storage object delivery. Byte/API proof separate.
insert into storage.objects(bucket_id,name) values('community-media','quarantine/'||(select value->>'id' from media_state where key='ticket')||'/image.jpg');
set local role authenticated;set local request.jwt.claim.role='authenticated';
select is((public.community_media('get',jsonb_build_object('id',(select value->>'id' from media_state where key='ticket')))->>'state'),'pending','Uploader sees pending status without publishing');
select is((select count(*) from storage.objects where bucket_id='community-media'),0::bigint,'Authenticated owner cannot directly read quarantine bucket');
set local request.jwt.claim.sub='c1600000-0000-4000-8000-000000000002';
select throws_ok($$select public.community_media_access((select (value->>'id')::uuid from media_state where key='ticket'),'thumbnail')$$,'P0001','community_unavailable','Approved follower cannot view an unreviewed upload');
set local request.jwt.claim.sub='c1600000-0000-4000-8000-000000000004';set local request.jwt.claims='{"aal":"aal1"}';
select throws_ok($$select public.community_media('review',jsonb_build_object('id',(select value->>'id' from media_state where key='ticket'),'decision','approve','reason','Fixture review'))$$,'P0001','community_access_denied','Named reviewer still requires MFA');
set local request.jwt.claims='{"aal":"aal2"}';
insert into media_state values('pendingStaffAccess',public.community_media_access((select (value->>'id')::uuid from media_state where key='ticket'),'thumbnail'));
select is((select value->>'path' from media_state where key='pendingStaffAccess'),'quarantine/'||(select value->>'id' from media_state where key='ticket')||'/thumbnail.jpg','Named MFA staff can inspect a pending quarantine image');
reset role;
select is((select count(*) from public.community_moderation_actions where target_type='media' and target_id=(select value->>'id' from media_state where key='ticket') and action='inspect' and staff_operator='c1600000-0000-4000-8000-000000000004'),1::bigint,'Pending inspection records actor target time and reason');
insert into media_state values('pendingStaffAudit',jsonb_build_object('id',(select id from public.community_moderation_actions where target_type='media' and target_id=(select value->>'id' from media_state where key='ticket') and action='inspect' and staff_operator='c1600000-0000-4000-8000-000000000004')));
set local role authenticated;
select is((public.community_media('review',jsonb_build_object('id',(select value->>'id' from media_state where key='ticket'),'decision','approve','reason','Fixture independent review'))->>'state'),'approved','Independent named MFA reviewer authorizes existing audience');
select throws_ok($$select public.community_media_access((select (value->>'id')::uuid from media_state where key='ticket'),'image')$$,'P0001','community_unavailable','Unrelated staff cannot bypass an approved image audience without a case');
set local request.jwt.claim.sub='c1600000-0000-4000-8000-000000000003';set local request.jwt.claims='{"aal":"aal1"}';
select throws_ok($$select public.community_media_access((select (value->>'id')::uuid from media_state where key='ticket'),'image')$$,'P0001','community_unavailable','Unrelated account denied byte path');
set local request.jwt.claim.sub='c1600000-0000-4000-8000-000000000002';
select is((public.community_media_access((select (value->>'id')::uuid from media_state where key='ticket'),'thumbnail')->>'path'),'quarantine/'||(select value->>'id' from media_state where key='ticket')||'/thumbnail.jpg','Approved follower gets only current authorized server path');
select is((select count(*) from storage.objects where bucket_id='community-media'),0::bigint,'Approved social audience still has no direct Storage read');
insert into media_state values('receipt',jsonb_build_object('id',(select id from public.community_issue_report_receipt('media',(select value->>'id' from media_state where key='ticket')))));
select is((select id from public.community_issue_report_receipt('media',(select value->>'id' from media_state where key='ticket'))),(select (value->>'id')::uuid from media_state where key='receipt'),'Repeated explicit media receipt returns the same unexpired evidence ID');
insert into media_state select 'report',jsonb_build_object('id',id) from public.community_submit_report('media',(select value->>'id' from media_state where key='ticket'),'unsafe_or_sexual_content',null,(select (value->>'id')::uuid from media_state where key='receipt'));
set local request.jwt.claim.sub='c1600000-0000-4000-8000-000000000004';set local request.jwt.claims='{"aal":"aal2"}';
select lives_ok($$select public.community_media_evidence_access((select (value->>'id')::uuid from media_state where key='report'),'image')$$,'MFA staff can inspect the approved image only through a current case');
set local request.jwt.claim.sub='c1600000-0000-4000-8000-000000000002';set local request.jwt.claims='{"aal":"aal1"}';
reset role;set local request.jwt.claim.role='service_role';
insert into public.community_blocks(blocker_user_id,blocked_user_id) values('c1600000-0000-4000-8000-000000000001','c1600000-0000-4000-8000-000000000002');
set local role authenticated;set local request.jwt.claim.role='authenticated';
select throws_ok($$select public.community_media_access((select (value->>'id')::uuid from media_state where key='ticket'),'thumbnail')$$,'P0001','community_unavailable','Bilateral block immediately revokes byte proxy access');
select lives_ok($$select * from public.community_submit_report('media',(select value->>'id' from media_state where key='ticket'),'unsafe_or_sexual_content',null,(select (value->>'id')::uuid from media_state where key='receipt'))$$,'Restricted receipt retains report after blocking');
set local request.jwt.claim.sub='c1600000-0000-4000-8000-000000000001';
select is((select count(*) from public.community_media_export('media',null,500)),1::bigint,'Owner exports their bounded asset metadata');
select is((select count(*) from public.community_media_export('mediaReviews',null,500)),1::bigint,'Owner gets review outcome without reviewer identity');
reset role;update public.community_feature_controls set enabled=false where feature='media';
set local role authenticated;
select is(jsonb_array_length(public.community_media('list','{"mine":"true"}')->'items'),1,'Owner can find their images for removal while feature frozen');
select lives_ok($$select public.community_media('delete',jsonb_build_object('id',(select value->>'id' from media_state where key='ticket')))$$,'Removal remains available while feature frozen');
reset role;
select is((select count(*) from public.community_media_cleanup_jobs where id=(select (value->>'id')::uuid from media_state where key='ticket')),1::bigint,'Deletion queues durable object cleanup');
select ok((select not_before>=now()+interval '29 days' from public.community_media_cleanup_jobs where id=(select (value->>'id')::uuid from media_state where key='ticket')),'Reported evidence retains restricted bytes for bounded case period');
delete from auth.users where id='c1600000-0000-4000-8000-000000000001';
select is((select target_id from public.community_moderation_actions where id=(select (value->>'id')::uuid from media_state where key='pendingStaffAudit')),'deleted','Auth subject erasure removes the no-case quarantine audit target');
select is((select reason from public.community_moderation_actions where id=(select (value->>'id')::uuid from media_state where key='pendingStaffAudit')),'Retained moderation audit metadata; evidence removed.','Auth subject erasure retains only the generic quarantine inspection record');
select ok((select staff_notes is null from public.community_moderation_actions where id=(select (value->>'id')::uuid from media_state where key='pendingStaffAudit')),'Erased quarantine inspection cannot retain private staff notes');
select is((select count(*) from public.community_media_assets where user_id='c1600000-0000-4000-8000-000000000001'),0::bigint,'Account deletion cascades live asset metadata');
select is((select count(*) from public.community_media_cleanup_jobs where id=(select (value->>'id')::uuid from media_state where key='ticket')),1::bigint,'Auth deletion cannot erase object cleanup tombstone');
set local role authenticated;set local request.jwt.claim.sub='c1600000-0000-4000-8000-000000000002';
select throws_ok($$select public.community_media_evidence_access((select (value->>'id')::uuid from media_state where key='report'),'image')$$,'P0001','community_access_denied','Reporter cannot retrieve retained case pixels');
insert into media_state select 'erasedReport',jsonb_build_object('id',id) from public.community_submit_report('media',(select value->>'id' from media_state where key='ticket'),'other',null,(select (value->>'id')::uuid from media_state where key='receipt'));
set local request.jwt.claim.sub='c1600000-0000-4000-8000-000000000004';set local request.jwt.claims='{"aal":"aal2"}';
select throws_ok($$select public.community_media_evidence_access((select (value->>'id')::uuid from media_state where key='erasedReport'),'image')$$,'P0001','community_unavailable','A fresh receipt-backed erased-subject case cannot resurrect deleted pixels');
select throws_ok($$select public.community_media_evidence_access((select (value->>'id')::uuid from media_state where key='report'),'image')$$,'P0001','community_unavailable','Erased Auth subject cannot return a fabricated case pixel path');
-- Each maintenance phase is bounded even when global cleanup has a backlog.
reset role;set local request.jwt.claim.role='service_role';
insert into public.community_media_cleanup_jobs(id,user_id,image_path,thumbnail_path,not_before,created_at)
select ('f1600000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'c1600000-0000-4000-8000-000000000001','synthetic/image','synthetic/thumbnail',now()+interval '30 days',now()-interval '1 minute' from generate_series(1,2)n;
insert into public.community_media_assets(id,user_id,generation,operation_id,digest,alt_text,state,lease_expires_at,created_at)
select ('a1600000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'c1600000-0000-4000-8000-000000000003',1,('b1600000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,repeat('c',64),'Synthetic expired upload','uploading',now()-interval '1 minute',now()-interval '1 hour' from generate_series(1,2)n;
insert into public.community_media_assets(id,user_id,generation,operation_id,digest,alt_text,state,created_at)
select ('a1600000-0000-4000-8001-'||lpad(n::text,12,'0'))::uuid,'c1600000-0000-4000-8000-000000000003',1,('b1600000-0000-4000-8001-'||lpad(n::text,12,'0'))::uuid,repeat('d',64),'Synthetic expired review','pending',now()-interval '8 days' from generate_series(1,2)n;
select public.community_media_cleanup('claim','{"limit":1}');
select is((select count(*) from public.community_media_cleanup_jobs where user_id='c1600000-0000-4000-8000-000000000001' and not_before>created_at+interval '10 minutes'),2::bigint,'One-item tick shortens only one erased-owner evidence hold');
select is((select count(*) from public.community_media_assets where user_id='c1600000-0000-4000-8000-000000000003' and state='uploading'),1::bigint,'One-item tick revokes only one expired upload');
select is((select count(*) from public.community_media_assets where user_id='c1600000-0000-4000-8000-000000000003' and state='pending'),1::bigint,'One-item tick revokes only one stale review');
select public.community_media_cleanup('claim','{"limit":1}');
select is((select count(*) from public.community_media_assets where user_id='c1600000-0000-4000-8000-000000000003' and state in('uploading','pending')),0::bigint,'Resumed maintenance advances each phase without starving already processed rows');
select public.community_media_cleanup('claim','{"limit":1}');
select is((select count(*) from public.community_media_cleanup_jobs where user_id='c1600000-0000-4000-8000-000000000001' and not_before>created_at+interval '10 minutes'),0::bigint,'Resumed orphan cleanup eventually drains all excessive evidence holds');
select * from finish();
rollback;
